// Class 12 English Core - Flamingo Poetry Chapter 9: My Mother at Sixty-six
// Fully standardized to English Core Blueprint & AGENTS.md guidelines

export const c12EngF9HtmlOverview = "\n<div style=\"padding: 18px; color: #F8FAFC; text-align: justify; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; line-height: 1.85; font-size: 15px;\">\n  <!-- Chapter Header Badge -->\n  <div style=\"background: linear-gradient(135deg, rgba(224, 64, 251, 0.18), rgba(15, 23, 42, 0.95)); border: 1.5px solid #E040FB; border-radius: 14px; padding: 22px; margin-bottom: 24px; box-shadow: 0 8px 24px rgba(0,0,0,0.35);\">\n    <div style=\"display: flex; align-items: center; gap: 12px; margin-bottom: 10px;\">\n      <span style=\"background: #E040FB; color: #0F172A; font-weight: 800; font-size: 12px; padding: 4px 10px; border-radius: 6px; text-transform: uppercase; letter-spacing: 1px;\">Poem 9 • Flamingo Poetry</span>\n      <span style=\"color: #94A3B8; font-size: 13px; font-weight: 600;\">Core Literature • Class 12 English</span>\n    </div>\n    <h1 style=\"color: #FFFFFF; font-size: 26px; font-weight: 800; margin: 0 0 8px 0; letter-spacing: -0.5px;\">My Mother at Sixty-six</h1>\n    <p style=\"color: #E040FB; font-size: 15px; font-weight: 600; margin: 0 0 12px 0;\">By Kamala Das (1934–2009) • Pen Name: Madhavikutty</p>\n    <p style=\"color: #CBD5E1; font-size: 14px; line-height: 1.6; margin: 0;\">A deeply poignant, confessional lyrical monologue exploring the fragile bond between a daughter and her ageing mother, capturing the anguish of separation, inevitable mortality, and the brave mask of an optimistic smile.</p>\n  </div>\n\n  <!-- Poet Background & Context -->\n  <div style=\"background: rgba(30, 41, 59, 0.7); border-left: 4px solid #E040FB; border-radius: 0 12px 12px 0; padding: 18px 20px; margin-bottom: 24px;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 10px 0; font-size: 18px; font-weight: 700;\">1. About the Poet & Confessional Aesthetic</h3>\n    <p style=\"margin: 0 0 10px 0;\">Kamala Das (born in Malabar, Kerala) is universally recognized as one of India's pre-eminent confessional poets, writing with unflinching emotional honesty, lyricism, and acute sensitivity to the intricacies of human relationships. Writing in both English and Malayalam (under the pen name <b style=\"color: #E040FB;\">Madhavikutty</b>), her verse explores the female experience, familial attachments, and existential vulnerability.</p>\n    <p style=\"margin: 0;\"><b style=\"color: #E040FB;\">The Single Continuous Cadence:</b> <i style=\"color: #E040FB;\">My Mother at Sixty-six</i> is composed in a single running sentence punctuated exclusively by commas and pauses (enjambment). This stream-of-consciousness technique mirrors the unceasing flow of thought, anxiety, and dread that surges through the daughter during an automobile ride to the airport.</p>\n  </div>\n\n  <!-- Stanza-by-Stanza Deep Analysis -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(255, 255, 255, 0.08); border-radius: 12px; padding: 20px; margin-bottom: 24px;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 16px 0; font-size: 18px; font-weight: 700;\">2. Stanza-by-Stanza Critical Analysis</h3>\n    \n    <div style=\"margin-bottom: 16px; padding-bottom: 14px; border-bottom: 1px dashed rgba(255,255,255,0.1);\">\n      <h4 style=\"color: #F1F5F9; font-size: 15px; margin: 0 0 8px 0;\"><b style=\"color: #E040FB;\">Lines 1–6: The Glimpse of Mortality in the Car</b></h4>\n      <p style=\"margin: 0; color: #CBD5E1; font-size: 14px;\">Driving from her ancestral home to Cochin airport on a Friday morning, the poet glances at her mother sitting beside her. The sixty-six-year-old woman is dozing with her mouth open. Her face is described as <i style=\"color: #FFFFFF;\">\"ashen like that of a corpse\"</i>—pale, drained of blood, and grey like cinders. The visceral sight strikes the poet with abrupt, painful realization: her mother has aged irrevocably and is edging toward death.</p>\n    </div>\n\n    <div style=\"margin-bottom: 16px; padding-bottom: 14px; border-bottom: 1px dashed rgba(255,255,255,0.1);\">\n      <h4 style=\"color: #F1F5F9; font-size: 15px; margin: 0 0 8px 0;\"><b style=\"color: #E040FB;\">Lines 7–12: The Diversion & Contrast with Vibrant Youth</b></h4>\n      <p style=\"margin: 0; color: #CBD5E1; font-size: 14px;\">Unable to bear the agony of this sudden insight, the poet hastily shifts her gaze outside the car window to put that terrifying thought away. The external world presents a sharp, vivid contrast: <i style=\"color: #FFFFFF;\">\"Young Trees sprinting\"</i> and <i style=\"color: #FFFFFF;\">\"merry children spilling out of their homes.\"</i> These dynamic images symbolize the exuberant momentum of life, vitality, youth, and uninhibited joyous energy, offering a momentary emotional sanctuary from the decaying body beside her.</p>\n    </div>\n\n    <div style=\"margin-bottom: 16px; padding-bottom: 14px; border-bottom: 1px dashed rgba(255,255,255,0.1);\">\n      <h4 style=\"color: #F1F5F9; font-size: 15px; margin: 0 0 8px 0;\"><b style=\"color: #E040FB;\">Lines 13–18: Airport Security Check & The Late Winter's Moon</b></h4>\n      <p style=\"margin: 0; color: #CBD5E1; font-size: 14px;\">After passing through the mandatory airport security check, the poet stands a few yards away and looks back at her mother once again. The mother's face appears <i style=\"color: #FFFFFF;\">\"wan, pale as a late winter's moon.\"</i> Just as a winter moon is obscured by thick fog, mist, and devoid of warmth or radiance, the mother has lost her youthful bloom and life energy, standing on the threshold of winter—the twilight of life.</p>\n    </div>\n\n    <div>\n      <h4 style=\"color: #F1F5F9; font-size: 15px; margin: 0 0 8px 0;\"><b style=\"color: #E040FB;\">Lines 19–24: The Familiar Ache & The Brave Parting Smile</b></h4>\n      <p style=\"margin: 0; color: #CBD5E1; font-size: 14px;\">The sight revives the poet's <i style=\"color: #FFFFFF;\">\"old familiar ache, my childhood's fear\"</i>—the primal dread of losing one's mother or being permanently separated from her. Yet, the daughter refuses to succumb to tears or distress her frail mother. Suppressing her inner terror, she utters reassuring parting words: <i style=\"color: #FFFFFF;\">\"see you soon, Amma,\"</i> and masks her sorrow behind a repeated, deliberate gesture: <i style=\"color: #FFFFFF;\">\"all I did was smile and smile and smile...\"</i></p>\n    </div>\n  </div>\n\n  <!-- Master Poetic Devices Table -->\n  <div style=\"background: rgba(30, 41, 59, 0.85); border: 1px solid rgba(255, 255, 255, 0.08); border-radius: 12px; padding: 20px; margin-bottom: 24px;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 16px 0; font-size: 18px; font-weight: 700;\">3. Master Literary & Poetic Devices Table</h3>\n    <div style=\"overflow-x: auto;\">\n      <table style=\"width: 100%; border-collapse: collapse; font-size: 14px; text-align: left;\">\n        <thead>\n          <tr style=\"background: rgba(224, 64, 251, 0.15); border-bottom: 2px solid #E040FB;\">\n            <th style=\"padding: 10px 12px; color: #E040FB;\">Poetic Device</th>\n            <th style=\"padding: 10px 12px; color: #FFFFFF;\">Example from Poem</th>\n            <th style=\"padding: 10px 12px; color: #CBD5E1;\">Poetic Significance & Explanation</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.06);\">\n            <td style=\"padding: 10px 12px; font-weight: bold; color: #E040FB;\">Simile</td>\n            <td style=\"padding: 10px 12px; color: #F1F5F9;\">\"face ashen like that of a corpse\"<br/>\"pale as a late winter's moon\"</td>\n            <td style=\"padding: 10px 12px; color: #CBD5E1;\">Directly compares mother's bloodless, grey face to a dead body (corpse) and her faded vitality to a hazy, dim winter moon.</td>\n          </tr>\n          <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.06); background: rgba(15, 23, 42, 0.4);\">\n            <td style=\"padding: 10px 12px; font-weight: bold; color: #E040FB;\">Personification</td>\n            <td style=\"padding: 10px 12px; color: #F1F5F9;\">\"Young Trees sprinting\"</td>\n            <td style=\"padding: 10px 12px; color: #CBD5E1;\">Trees are personified as youthful runners dashing past, emphasizing the relentless, rapid passage of time and fleeting youth.</td>\n          </tr>\n          <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.06);\">\n            <td style=\"padding: 10px 12px; font-weight: bold; color: #E040FB;\">Metaphor</td>\n            <td style=\"padding: 10px 12px; color: #F1F5F9;\">\"merry children spilling out\"</td>\n            <td style=\"padding: 10px 12px; color: #CBD5E1;\">Children rushing enthusiastically out of homes are compared to liquid overflowing a container, symbolizing abundant vitality and spontaneous joy.</td>\n          </tr>\n          <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.06); background: rgba(15, 23, 42, 0.4);\">\n            <td style=\"padding: 10px 12px; font-weight: bold; color: #E040FB;\">Contrast / Juxtaposition</td>\n            <td style=\"padding: 10px 12px; color: #F1F5F9;\">Dozing frail mother vs. Sprinting trees & spilling children</td>\n            <td style=\"padding: 10px 12px; color: #CBD5E1;\">Sharp juxtaposition between sluggish physical decay/impending mortality inside the car and vibrant, energetic youth outside.</td>\n          </tr>\n          <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.06);\">\n            <td style=\"padding: 10px 12px; font-weight: bold; color: #E040FB;\">Repetition (Tautology)</td>\n            <td style=\"padding: 10px 12px; color: #F1F5F9;\">\"smile and smile and smile...\"</td>\n            <td style=\"padding: 10px 12px; color: #CBD5E1;\">Repetition emphasizes the desperate, artificial effort to maintain a cheerful facade and suppress overwhelming sorrow and tears.</td>\n          </tr>\n          <tr>\n            <td style=\"padding: 10px 12px; font-weight: bold; color: #E040FB;\">Alliteration</td>\n            <td style=\"padding: 10px 12px; color: #F1F5F9;\">\"my mother\"<br/>\"see you soon\"<br/>\"smile and smile\"</td>\n            <td style=\"padding: 10px 12px; color: #CBD5E1;\">Repetition of initial consonant sounds ('m', 's') creates tender lyricism and rhythmic softness, reinforcing maternal tenderness.</td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n\n  <!-- Vocabulary Glossary -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border-left: 4px solid #E040FB; border-radius: 0 12px 12px 0; padding: 18px 20px;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 12px 0; font-size: 17px; font-weight: 700;\">4. Essential Stanza Vocabulary</h3>\n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; font-size: 13px;\">\n      <div><b style=\"color: #E040FB;\">Doze:</b> Sleep lightly or briefly; nap unconsciously.</div>\n      <div><b style=\"color: #E040FB;\">Ashen:</b> Very pale, bloodless, grey like wood ash or cinders.</div>\n      <div><b style=\"color: #E040FB;\">Corpse:</b> A dead human body.</div>\n      <div><b style=\"color: #E040FB;\">Spilling:</b> Overflowing and rushing out eagerly in large numbers.</div>\n      <div><b style=\"color: #E040FB;\">Wan:</b> Dim, pale, faint, giving the impression of illness or exhaustion.</div>\n      <div><b style=\"color: #E040FB;\">Ache:</b> Deep, continuous emotional pain or dull distress.</div>\n    </div>\n  </div>\n</div>\n";

export const c12EngF9HtmlSolutions = "\n<div style=\"padding: 16px; color: #F8FAFC; text-align: justify; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; line-height: 1.85; font-size: 15px;\">\n\n  <!-- SECTION A: EXTRACT-BASED QUESTIONS -->\n  <div style=\"margin-bottom: 30px;\">\n    <div style=\"background: linear-gradient(135deg, rgba(224, 64, 251, 0.25), rgba(15, 23, 42, 0.95)); border: 1.5px solid #E040FB; border-radius: 12px; padding: 14px 18px; margin-bottom: 20px;\">\n      <h2 style=\"color: #FFFFFF; font-size: 20px; font-weight: 800; margin: 0 0 4px 0;\">SECTION A: Extract-Based Questions (16 Marks)</h2>\n      <p style=\"color: #E040FB; font-size: 13px; font-weight: 600; margin: 0;\">Board Pattern: 4 Objective Extracts • 4 Questions Each • Continuous Q1 to Q16</p>\n    </div>\n\n    <!-- Extract 1 -->\n    <div style=\"background: rgba(30, 41, 59, 0.7); border-left: 4px solid #E040FB; border-radius: 0 10px 10px 0; padding: 14px 18px; margin-bottom: 16px;\">\n      <p style=\"font-style: italic; color: #E2E8F0; margin: 0 0 8px 0; font-size: 14px;\">\n        \"Driving from my parent's<br/>\n        home to Cochin last Friday<br/>\n        morning, I saw my mother,<br/>\n        beside me,<br/>\n        doze, open mouthed, her face<br/>\n        ashen like that<br/>\n        of a corpse...\"\n      </p>\n      <span style=\"color: #E040FB; font-size: 12px; font-weight: 700;\">— Extract 1 (Lines 1–7)</span>\n    </div>\n\n    <!-- Q1 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(224, 64, 251, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #E040FB; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q1: Where was the poet driving to, and who was sitting beside her?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #E040FB; font-weight: bold;\">✓ Answer:</span> The poet Kamala Das was driving from her parents' ancestral home to Cochin airport on a Friday morning. Her sixty-six-year-old mother was sitting beside her in the car.</p>\n    </div>\n\n    <!-- Q2 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(224, 64, 251, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #E040FB; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q2: What physical condition was the mother in during the car ride?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #E040FB; font-weight: bold;\">✓ Answer:</span> The mother was dozing lightly with her mouth open. Her face was pale, bloodless, and grey like ash, giving her the appearance of a lifeless corpse.</p>\n    </div>\n\n    <!-- Q3 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(224, 64, 251, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #E040FB; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q3: Identify and explain the poetic device in \"face ashen like that of a corpse\".</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #E040FB; font-weight: bold;\">✓ Answer:</span> <b style=\"color: #E040FB;\">Simile</b>. The poet directly compares her mother's pale, bloodless face to that of a dead body (corpse) using the connective word 'like', underscoring the chilling reality of ageing and impending death.</p>\n    </div>\n\n    <!-- Q4 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(224, 64, 251, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 22px;\">\n      <h3 style=\"color: #E040FB; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q4: What painful realization dawned upon the poet?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #E040FB; font-weight: bold;\">✓ Answer:</span> The poet painfully realized that her mother had grown truly old and frail, and was nearing the final stages of life, making the prospect of permanent loss real and immediate.</p>\n    </div>\n\n    <!-- Extract 2 -->\n    <div style=\"background: rgba(30, 41, 59, 0.7); border-left: 4px solid #E040FB; border-radius: 0 10px 10px 0; padding: 14px 18px; margin-bottom: 16px;\">\n      <p style=\"font-style: italic; color: #E2E8F0; margin: 0 0 8px 0; font-size: 14px;\">\n        \"...and felt that thought away,<br/>\n        and looked out at Young<br/>\n        Trees sprinting, the merry children spilling<br/>\n        out of their homes...\"\n      </p>\n      <span style=\"color: #E040FB; font-size: 12px; font-weight: 700;\">— Extract 2 (Lines 7–12)</span>\n    </div>\n\n    <!-- Q5 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(224, 64, 251, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #E040FB; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q5: Why did the poet look out of the car window?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #E040FB; font-weight: bold;\">✓ Answer:</span> The poet looked out to divert her mind and put away the distressing thought of her mother's imminent death and frail physical condition, seeking psychological relief in external scenes.</p>\n    </div>\n\n    <!-- Q6 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(224, 64, 251, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #E040FB; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q6: What do the \"Young Trees sprinting\" symbolize?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #E040FB; font-weight: bold;\">✓ Answer:</span> The sprinting trees symbolize youth, rapid passage of time, and active life. Viewed from the speeding car, they appear to run backward, symbolizing how swiftly youth slips away into old age.</p>\n    </div>\n\n    <!-- Q7 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(224, 64, 251, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #E040FB; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q7: Identify the poetic device in \"merry children spilling out of their homes\".</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #E040FB; font-weight: bold;\">✓ Answer:</span> <b style=\"color: #E040FB;\">Metaphor</b>. The spontaneous rushing out of joyful children is compared to a liquid overflowing from a vessel, signifying boundless energy, vitality, and uninhibited happiness.</p>\n    </div>\n\n    <!-- Q8 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(224, 64, 251, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 22px;\">\n      <h3 style=\"color: #E040FB; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q8: How does the scene outside contrast with the scene inside the car?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #E040FB; font-weight: bold;\">✓ Answer:</span> Outside, there is vigorous life, movement, speed, and youth (sprinting trees, joyous children); inside, there is stillness, decay, silence, and impending mortality represented by the sleeping, pale mother.</p>\n    </div>\n\n    <!-- Extract 3 -->\n    <div style=\"background: rgba(30, 41, 59, 0.7); border-left: 4px solid #E040FB; border-radius: 0 10px 10px 0; padding: 14px 18px; margin-bottom: 16px;\">\n      <p style=\"font-style: italic; color: #E2E8F0; margin: 0 0 8px 0; font-size: 14px;\">\n        \"...but after the airport's<br/>\n        security check, standing a few yards<br/>\n        away, I looked again at her, wan,<br/>\n        pale<br/>\n        as a late winter's moon...\"\n      </p>\n      <span style=\"color: #E040FB; font-size: 12px; font-weight: 700;\">— Extract 3 (Lines 13–18)</span>\n    </div>\n\n    <!-- Q9 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(224, 64, 251, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #E040FB; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q9: What did the poet do after the airport security check?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #E040FB; font-weight: bold;\">✓ Answer:</span> After clearing security, the poet stood a few yards away and looked back attentively at her mother once more to take in her appearance before parting.</p>\n    </div>\n\n    <!-- Q10 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(224, 64, 251, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #E040FB; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q10: Why is the mother compared to a \"late winter's moon\"?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #E040FB; font-weight: bold;\">✓ Answer:</span> A late winter's moon appears dim, misty, and devoid of warmth or shine due to fog and haze. Similarly, the mother has lost her youthful radiance, skin luster, and physical strength, entering the winter season of life.</p>\n    </div>\n\n    <!-- Q11 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(224, 64, 251, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #E040FB; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q11: What do the words \"wan\" and \"pale\" suggest?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #E040FB; font-weight: bold;\">✓ Answer:</span> \"Wan\" and \"pale\" convey ill-health, exhaustion, bloodlessness, and fragility, highlighting the mother's advanced age and declining vitality.</p>\n    </div>\n\n    <!-- Q12 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(224, 64, 251, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 22px;\">\n      <h3 style=\"color: #E040FB; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q12: Identify the poetic device in \"wan, pale as a late winter's moon\".</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #E040FB; font-weight: bold;\">✓ Answer:</span> <b style=\"color: #E040FB;\">Simile</b>. The comparison uses 'as' to connect the mother's faded countenance to the hazy, dim winter moon.</p>\n    </div>\n\n    <!-- Extract 4 -->\n    <div style=\"background: rgba(30, 41, 59, 0.7); border-left: 4px solid #E040FB; border-radius: 0 10px 10px 0; padding: 14px 18px; margin-bottom: 16px;\">\n      <p style=\"font-style: italic; color: #E2E8F0; margin: 0 0 8px 0; font-size: 14px;\">\n        \"...and felt that old<br/>\n        familiar ache, my childhood's fear,<br/>\n        but all I said was, see you soon,<br/>\n        Amma,<br/>\n        all I did was smile and smile and<br/>\n        smile...\"\n      </p>\n      <span style=\"color: #E040FB; font-size: 12px; font-weight: 700;\">— Extract 4 (Lines 19–24)</span>\n    </div>\n\n    <!-- Q13 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(224, 64, 251, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #E040FB; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q13: What was the poet's \"childhood's fear\"?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #E040FB; font-weight: bold;\">✓ Answer:</span> Her childhood fear was the terrifying anxiety of losing her mother or being separated from her. As an adult, this fear resurfaces as the concrete dread of her mother's impending death.</p>\n    </div>\n\n    <!-- Q14 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(224, 64, 251, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #E040FB; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q14: What were the poet's parting words to her mother?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #E040FB; font-weight: bold;\">✓ Answer:</span> Her parting words were: <i>\"see you soon, Amma.\"</i> They express hope and reassurance, masking her inward dread that she might never see her mother alive again.</p>\n    </div>\n\n    <!-- Q15 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(224, 64, 251, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #E040FB; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q15: Why did the poet \"smile and smile and smile\"?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #E040FB; font-weight: bold;\">✓ Answer:</span> The repeated smile was a brave facade to hide her grief, tears, and anxiety. She smiled to reassure her mother and leave her with an uplifting memory rather than emotional pain.</p>\n    </div>\n\n    <!-- Q16 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(224, 64, 251, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 22px;\">\n      <h3 style=\"color: #E040FB; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q16: Identify the poetic device in \"smile and smile and smile\".</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #E040FB; font-weight: bold;\">✓ Answer:</span> <b style=\"color: #E040FB;\">Repetition</b> (and polysyndeton). The triple repetition underscores the sustained, deliberate effort required to mask her overwhelming grief behind a smile.</p>\n    </div>\n  </div>\n\n  <!-- SECTION B: SHORT ANSWER QUESTIONS -->\n  <div style=\"margin-bottom: 30px;\">\n    <div style=\"background: linear-gradient(135deg, rgba(224, 64, 251, 0.25), rgba(15, 23, 42, 0.95)); border: 1.5px solid #E040FB; border-radius: 12px; padding: 14px 18px; margin-bottom: 20px;\">\n      <h2 style=\"color: #FFFFFF; font-size: 20px; font-weight: 800; margin: 0 0 4px 0;\">SECTION B: Short Answer Questions (3 Marks • 40–50 Words)</h2>\n      <p style=\"color: #E040FB; font-size: 13px; font-weight: 600; margin: 0;\">Board Standard: Confessional Lyricism & Character Analysis • 12 Questions (Q17 to Q28)</p>\n    </div>\n\n    <!-- Q17 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border-left: 3px solid #E040FB; border-radius: 0 10px 10px 0; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #E040FB; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q17: Why did Kamala Das describe her mother's face as 'ashen like that of a corpse'?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #E040FB; font-weight: bold;\">✓ Answer:</span> At sixty-six, her mother's face had lost all youthful color, vitality, and warmth. In sleep, with her mouth slightly open and her complexion grey and pale like ash, she bore an uncanny resemblance to a lifeless body, startling the poet into confronting mortality.</p>\n    </div>\n\n    <!-- Q18 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border-left: 3px solid #E040FB; border-radius: 0 10px 10px 0; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #E040FB; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q18: Why are the young trees described as 'sprinting'?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #E040FB; font-weight: bold;\">✓ Answer:</span> As the car moves forward at high speed, roadside trees appear to sprint backward. Poetically, this personification symbolizes the fast, unstoppable pace of time, youth slipping into old age, and the energetic vitality of the natural world.</p>\n    </div>\n\n    <!-- Q19 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border-left: 3px solid #E040FB; border-radius: 0 10px 10px 0; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #E040FB; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q19: What do the 'merry children spilling out of their homes' represent?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #E040FB; font-weight: bold;\">✓ Answer:</span> The children represent the dawn of life, exuberance, and spontaneous joy. Their overflowing energy contrasts sharply with the ageing mother's passive, silent frailty inside the car, emphasizing the cyclical nature of human existence.</p>\n    </div>\n\n    <!-- Q20 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border-left: 3px solid #E040FB; border-radius: 0 10px 10px 0; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #E040FB; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q20: Why has the mother been compared to the 'late winter's moon'?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #E040FB; font-weight: bold;\">✓ Answer:</span> In late winter, the moon loses its clarity and brightness, masked by thick fog and cold mists. Similarly, the mother's face has lost its vitality, charm, and glow due to old age, symbolizing the winter season of human life.</p>\n    </div>\n\n    <!-- Q21 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border-left: 3px solid #E040FB; border-radius: 0 10px 10px 0; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #E040FB; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q21: What is the 'familiar ache' mentioned by the poet?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #E040FB; font-weight: bold;\">✓ Answer:</span> The 'familiar ache' is the emotional pang of separation from her mother that she first felt in early childhood. Seeing her mother's frail, aged condition revives that dread, now intensified by the prospect of permanent loss through death.</p>\n    </div>\n\n    <!-- Q22 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border-left: 3px solid #E040FB; border-radius: 0 10px 10px 0; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #E040FB; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q22: How does Kamala Das manage to hide her anxiety at the airport?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #E040FB; font-weight: bold;\">✓ Answer:</span> Kamala Das maintains emotional composure by offering reassuring words (<i>\"see you soon, Amma\"</i>) and putting on a continuous, deliberate smile. This mask prevents her mother from sensing her inner panic and despair.</p>\n    </div>\n\n    <!-- Q23 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border-left: 3px solid #E040FB; border-radius: 0 10px 10px 0; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #E040FB; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q23: What does the structure of a single continuous sentence signify in this poem?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #E040FB; font-weight: bold;\">✓ Answer:</span> The single, enjambed sentence mirrors the unbroken flow of anxious thoughts, observations, and memories rushing through the poet's mind, creating an intimate, stream-of-consciousness effect.</p>\n    </div>\n\n    <!-- Q24 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border-left: 3px solid #E040FB; border-radius: 0 10px 10px 0; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #E040FB; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q24: What emotional conflict does the poet experience at the departure gate?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #E040FB; font-weight: bold;\">✓ Answer:</span> She is torn between her personal and professional commitments requiring her to fly away, and her filial duty and intense love for her ageing mother, whose frailty makes her depart with deep guilt and anxiety.</p>\n    </div>\n\n    <!-- Q25 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border-left: 3px solid #E040FB; border-radius: 0 10px 10px 0; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #E040FB; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q25: Why does the poet repeat the word 'smile' thrice in the concluding line?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #E040FB; font-weight: bold;\">✓ Answer:</span> The repetition highlights the tremendous emotional struggle required to sustain the smile. It emphasizes the artificial, deliberate nature of her outward calm, functioning as a defensive wall against her tears.</p>\n    </div>\n\n    <!-- Q26 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border-left: 3px solid #E040FB; border-radius: 0 10px 10px 0; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #E040FB; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q26: What role does the physical distance ('a few yards away') play at the airport?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #E040FB; font-weight: bold;\">✓ Answer:</span> Standing \"a few yards away\" creates physical and emotional separation. It anticipates the impending permanent separation between daughter and mother, allowing the poet to view her with heartbreaking clarity.</p>\n    </div>\n\n    <!-- Q27 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border-left: 3px solid #E040FB; border-radius: 0 10px 10px 0; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #E040FB; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q27: How does the poet capture the universal experience of dealing with ageing parents?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #E040FB; font-weight: bold;\">✓ Answer:</span> The poem articulates the universal guilt and helplessness children feel as they grow up, pursue careers, and find themselves unable to halt or reverse the steady physical decline of their ageing parents.</p>\n    </div>\n\n    <!-- Q28 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border-left: 3px solid #E040FB; border-radius: 0 10px 10px 0; padding: 14px 16px; margin-bottom: 22px;\">\n      <h3 style=\"color: #E040FB; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q28: What is the significance of the Friday morning journey?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #E040FB; font-weight: bold;\">✓ Answer:</span> Setting the poem during an ordinary, routine morning journey underscores that awareness of mortality often strikes unexpectedly during mundane everyday moments, rendering the realization all the more poignant.</p>\n    </div>\n  </div>\n\n  <!-- SECTION C: LONG ANSWER QUESTIONS -->\n  <div style=\"margin-bottom: 30px;\">\n    <div style=\"background: linear-gradient(135deg, rgba(224, 64, 251, 0.25), rgba(15, 23, 42, 0.95)); border: 1.5px solid #E040FB; border-radius: 12px; padding: 14px 18px; margin-bottom: 20px;\">\n      <h2 style=\"color: #FFFFFF; font-size: 20px; font-weight: 800; margin: 0 0 4px 0;\">SECTION C: Long Analytical Questions (6 Marks • 120–150 Words)</h2>\n      <p style=\"color: #E040FB; font-size: 13px; font-weight: 600; margin: 0;\">3-Tier Model: Psychological Realism • Poetic Structure • Thematic Resolution • Q29 to Q34</p>\n    </div>\n\n    <!-- Q29 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(224, 64, 251, 0.3); border-radius: 12px; padding: 18px; margin-bottom: 18px;\">\n      <h3 style=\"color: #E040FB; font-size: 16px; font-weight: 700; margin: 0 0 10px 0;\">Q29: Analyze the themes of ageing, separation, and filial responsibility in Kamala Das's \"My Mother at Sixty-six\".</h3>\n      <p style=\"margin: 0 0 8px 0;\"><span style=\"color: #E040FB; font-weight: bold;\">✓ Answer:</span></p>\n      <p style=\"margin: 0 0 8px 0;\"><b style=\"color: #E040FB;\">1. The Inevitability of Ageing:</b> Kamala Das's poem captures the quiet tragedy of witnessing a parent grow old. The sixty-six-year-old mother, dozing open-mouthed with an \"ashen face like that of a corpse\", represents the relentless physical decay that accompanies old age. The realization is unvarnished: the person who once nurtured the daughter is now frail and close to the end of life.</p>\n      <p style=\"margin: 0 0 8px 0;\"><b style=\"color: #E040FB;\">2. The Agony of Separation & Helplessness:</b> The poem captures the complex guilt of modern life. The poet must depart for Cochin and catch her flight, compelled by adult responsibilities, yet she is paralyzed by the dread that this farewell might be her last. Her \"childhood's fear\" of losing her mother resurfaces, now carrying existential weight.</p>\n      <p style=\"margin: 0;\"><b style=\"color: #E040FB;\">3. Critical Conclusion:</b> Unable to reverse time, the daughter resorts to an act of emotional bravery—offering words of hope (<i>\"see you soon, Amma\"</i>) and smiling repeatedly to give comfort, turning a moment of grief into a quiet testament of filial love.</p>\n    </div>\n\n    <!-- Q30 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(224, 64, 251, 0.3); border-radius: 12px; padding: 18px; margin-bottom: 18px;\">\n      <h3 style=\"color: #E040FB; font-size: 16px; font-weight: 700; margin: 0 0 10px 0;\">Q30: How does Kamala Das use contrast and imagery to heighten the emotional intensity of the poem?</h3>\n      <p style=\"margin: 0 0 8px 0;\"><span style=\"color: #E040FB; font-weight: bold;\">✓ Answer:</span></p>\n      <p style=\"margin: 0 0 8px 0;\"><b style=\"color: #E040FB;\">1. Interior vs. Exterior Contrast:</b> The poem is built on a sharp juxtaposition between the world inside the car and the world outside. Inside, the mother sits motionless, pale and silent, embodying physical decline. To escape this painful sight, the poet looks out the window at \"Young Trees sprinting\" and \"merry children spilling out of their homes\"—scenes overflowing with vitality, movement, and joy.</p>\n      <p style=\"margin: 0 0 8px 0;\"><b style=\"color: #E040FB;\">2. Similes of Decay:</b> The imagery of decay is reinforced through two similes: the mother's face is first likened to an \"ashen corpse\" and later to a \"late winter's moon\". The winter moon—pale, hazy, and stripped of warmth—mirrors the mother's waning vitality as she reaches the winter of her life.</p>\n      <p style=\"margin: 0;\"><b style=\"color: #E040FB;\">3. Critical Conclusion:</b> By contrasting the energy of youth with the stillness of old age, Das sharpens the poem's emotional impact, underscoring the bittersweet transience of human life.</p>\n    </div>\n\n    <!-- Q31 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(224, 64, 251, 0.3); border-radius: 12px; padding: 18px; margin-bottom: 18px;\">\n      <h3 style=\"color: #E040FB; font-size: 16px; font-weight: 700; margin: 0 0 10px 0;\">Q31: Discuss the significance of the concluding lines: \"all I said was, see you soon, Amma, all I did was smile and smile and smile...\"</h3>\n      <p style=\"margin: 0 0 8px 0;\"><span style=\"color: #E040FB; font-weight: bold;\">✓ Answer:</span></p>\n      <p style=\"margin: 0 0 8px 0;\"><b style=\"color: #E040FB;\">1. Linguistic Restraint & Hope:</b> The parting words <i>\"see you soon, Amma\"</i> convey optimism while masking deep inner turmoil. The poet avoids sharing her fears, choosing instead to offer words of comfort that reassure her mother and preserve a sense of continuity.</p>\n      <p style=\"margin: 0 0 8px 0;\"><b style=\"color: #E040FB;\">2. The Mask of the Smile:</b> The repetition of \"smile and smile and smile\" emphasizes the deliberate effort required to maintain this composure. The smile is not born of happiness, but serves as a shield to hide her sorrow and prevent her mother from sensing her anxiety.</p>\n      <p style=\"margin: 0;\"><b style=\"color: #E040FB;\">3. Critical Conclusion:</b> The conclusion captures the quiet dignity of familial love, showing how emotional strength often takes the form of concealing one's own pain to spare a loved one distress.</p>\n    </div>\n\n    <!-- Q32 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(224, 64, 251, 0.3); border-radius: 12px; padding: 18px; margin-bottom: 18px;\">\n      <h3 style=\"color: #E040FB; font-size: 16px; font-weight: 700; margin: 0 0 10px 0;\">Q32: Examine \"My Mother at Sixty-six\" as a confessional poem characterized by stream-of-consciousness narration.</h3>\n      <p style=\"margin: 0 0 8px 0;\"><span style=\"color: #E040FB; font-weight: bold;\">✓ Answer:</span></p>\n      <p style=\"margin: 0 0 8px 0;\"><b style=\"color: #E040FB;\">1. Confessional Candour:</b> As a confessional poet, Kamala Das writes with unflinching emotional authenticity. She does not romanticize her mother's ageing or present idealized familial peace; rather, she candidly reveals her instinctive horror upon seeing her mother's corpse-like appearance and her urge to look away.</p>\n      <p style=\"margin: 0 0 8px 0;\"><b style=\"color: #E040FB;\">2. Stream of Consciousness Structure:</b> The entire poem unfolds in a single continuous sentence separated only by commas. This syntactic choice mirrors the uninterrupted flow of thoughts, observations, and memories flashing through the daughter's mind during the drive.</p>\n      <p style=\"margin: 0;\"><b style=\"color: #E040FB;\">3. Critical Conclusion:</b> Through this natural, uninhibited style, Das captures a deeply private emotional moment, creating a poem of resonant intimacy and universal relevance.</p>\n    </div>\n\n    <!-- Q33 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(224, 64, 251, 0.3); border-radius: 12px; padding: 18px; margin-bottom: 18px;\">\n      <h3 style=\"color: #E040FB; font-size: 16px; font-weight: 700; margin: 0 0 10px 0;\">Q33: How does the poem portray the psychological transition from childhood insecurity to adult grief?</h3>\n      <p style=\"margin: 0 0 8px 0;\"><span style=\"color: #E040FB; font-weight: bold;\">✓ Answer:</span></p>\n      <p style=\"margin: 0 0 8px 0;\"><b style=\"color: #E040FB;\">1. Childhood Insecurity:</b> In childhood, separation anxiety is an irrational fear—a child's instinctual panic at losing sight of its mother in a crowd or during routine absences, rooted in dependency and need for protection.</p>\n      <p style=\"margin: 0 0 8px 0;\"><b style=\"color: #E040FB;\">2. The Adult Realization:</b> In adulthood, this irrational fear solidifies into a concrete reality. Standing at the airport, the poet recognizes that separation is no longer a temporary absence, but the looming permanence of biological death brought on by her mother's advanced age.</p>\n      <p style=\"margin: 0;\"><b style=\"color: #E040FB;\">3. Critical Conclusion:</b> The poem links these two phases of life, illustrating how the child's vulnerability endures within the adult, even as mature responsibilities demand composure in the face of loss.</p>\n    </div>\n\n    <!-- Q34 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(224, 64, 251, 0.3); border-radius: 12px; padding: 18px; margin-bottom: 22px;\">\n      <h3 style=\"color: #E040FB; font-size: 16px; font-weight: 700; margin: 0 0 10px 0;\">Q34: Evaluate the significance of the poem's title and its emotional understatement.</h3>\n      <p style=\"margin: 0 0 8px 0;\"><span style=\"color: #E040FB; font-weight: bold;\">✓ Answer:</span></p>\n      <p style=\"margin: 0 0 8px 0;\"><b style=\"color: #E040FB;\">1. Objective Title vs. Deep Subjectivity:</b> The title, <i>My Mother at Sixty-six</i>, appears neutral and descriptive, almost like a photograph's caption. Yet beneath this matter-of-fact label lies an intensely personal meditation on mortality, vulnerability, and love.</p>\n      <p style=\"margin: 0 0 8px 0;\"><b style=\"color: #E040FB;\">2. Power of Understatement:</b> The poet avoids melodramatic outbursts or sentimental excess. She does not openly weep at the airport or engage in dramatic goodbyes; she simply looks, reflects, and smiles. The understated nature of these gestures amplifies the emotional resonance of the poem.</p>\n      <p style=\"margin: 0;\"><b style=\"color: #E040FB;\">3. Critical Conclusion:</b> By pairing a straightforward title with restrained, honest emotion, Das creates an enduring portrait of quiet grief and resilient filial devotion.</p>\n    </div>\n  </div>\n\n  <!-- SECTION D: NCERT TEXTBOOK EXERCISES -->\n  <div style=\"margin-bottom: 20px;\">\n    <div style=\"background: linear-gradient(135deg, rgba(224, 64, 251, 0.25), rgba(15, 23, 42, 0.95)); border: 1.5px solid #E040FB; border-radius: 12px; padding: 14px 18px; margin-bottom: 20px;\">\n      <h2 style=\"color: #FFFFFF; font-size: 20px; font-weight: 800; margin: 0 0 4px 0;\">SECTION D: NCERT Textbook Exercises (Thinking About The Poem)</h2>\n      <p style=\"color: #E040FB; font-size: 13px; font-weight: 600; margin: 0;\">Official Curriculum Solutions • Questions Q35 to Q38</p>\n    </div>\n\n    <!-- Q35 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(224, 64, 251, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #E040FB; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q35: What is the kind of pain and ache that the poet feels?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #E040FB; font-weight: bold;\">✓ Answer:</span> The pain and ache that Kamala Das feels is the acute emotional agony of witnessing her mother's physical decline and realizing that she is nearing the end of her life. It revives her childhood dread of separation, compounded by adult helplessness and guilt at having to leave her aged mother behind.</p>\n    </div>\n\n    <!-- Q36 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(224, 64, 251, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #E040FB; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q36: Why are the young trees described as 'sprinting'?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #E040FB; font-weight: bold;\">✓ Answer:</span> The young trees appear to sprint backward when observed from the window of the fast-moving car. Symbolically, this personification contrasts the swift passage of time and the energetic vitality of youth with the passive stillness and frailty of the poet's ageing mother.</p>\n    </div>\n\n    <!-- Q37 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(224, 64, 251, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #E040FB; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q37: Why has the poet brought in the image of the merry children 'spilling out of their homes'?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #E040FB; font-weight: bold;\">✓ Answer:</span> The poet brings in the image of the merry children spilling out of their homes to present a vivid contrast to the atmosphere inside the car. While the mother embodies old age, decay, and stillness, the exuberant children represent vitality, youth, and spontaneous joy, providing a temporary diversion from the thought of mortality.</p>\n    </div>\n\n    <!-- Q38 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(224, 64, 251, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #E040FB; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q38: Why has the mother been compared to the 'late winter's moon'?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #E040FB; font-weight: bold;\">✓ Answer:</span> The mother is compared to a 'late winter's moon' because winter is the final season of the year, symbolizing the twilight of human life. A late winter moon looks hazy, pale, and dim behind fog and mist, lacking brightness; similarly, the mother has lost her youthful radiance, vitality, and strength due to old age.</p>\n    </div>\n  </div>\n\n</div>\n";

